import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 sdata[];
.visible .entry conv3d_ncdhw(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 K,
    .param .u32 P,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 has_bias
)
{
    .reg .pred p0, p1, p2, p3, p4, p5, p6, p7;
    .reg .pred px0, px1, px_ok, py0, py1, py_ok, pz0, pz1, pz_ok, p_yz_ok, pbias0, pstore;
     .reg .pred pal0, pal1, pal2, pL, pV, pR;
    .reg .b64 xbase, wbase, bbase, ybase;
    .reg .b64 addr_x, addr_w, addr_b, addr_y;
    .reg .b64 smem_base, w_sh_ptr, x_sh_ptr, addr_s, addr_plane, addr_sv, addr_sw, addr_sx;
    .reg .b64 addr_xv;
    .reg .u32 rN, rCin, rCout, rD, rH, rW, rK, rP, rDout, rHout, rWout, rHasBias;
    .reg .u32 r_tid, r_bdim, r_bx, r_by, r_bz;
    .reg .u32 r_wout_start, r_wout;
    .reg .u32 r_t, r_tmp1, r_tmp2, r_tmp3;
    .reg .u32 r_n, r_oc, r_dout, r_hout;
    .reg .u32 r_ic, r_kz, r_ky, r_kx;
    .reg .u32 r_base_w, r_w_idx;
    .reg .u32 r_base0, r_x_idx, ru_sx, ru_sy, ru_sz;
     .reg .u32 r_stripe_len, r_smem_stride;
    .reg .u32 r_vec_len, r_off_elems, r_tail_start, r_align0, r_left_cnt, r_right_cnt, r_vec_off_base, r_tmp_u0, r_tmp_u1;
    .reg .u32 rKK, r_plane_off, r_vec_len2;
    .reg .s32 sP, s_wout_start, s_x_base, s_hout, s_dout, s_y_base, s_z_base, s_z, s_y, s_xi;
    .reg .s32 s_start, s_end, s_mid_start, s_mid_end, s_tmpa, s_tmpb;
    .reg .f32 acc, xval, wval, xval2, wval2, bval, vx0, vx1, vx2, vx3;
    // Load pointers
    ld.param.u64 xbase, [x_ptr];
    ld.param.u64 wbase, [w_ptr];
    ld.param.u64 bbase, [b_ptr];
    ld.param.u64 ybase, [y_ptr];
    // Load sizes
    ld.param.u32 rN, [N];
    ld.param.u32 rCin, [Cin];
    ld.param.u32 rCout, [Cout];
    ld.param.u32 rD, [D];
    ld.param.u32 rH, [H];
    ld.param.u32 rW, [W];
    ld.param.u32 rK, [K];
    ld.param.u32 rP, [P];
    ld.param.u32 rDout, [Dout];
    ld.param.u32 rHout, [Hout];
    ld.param.u32 rWout, [Wout];
    ld.param.u32 rHasBias, [has_bias];
    // Thread/block indices
    mov.u32 r_tid, %tid.x;
    mov.u32 r_bdim, %ntid.x;
    mov.u32 r_bx, %ctaid.x;
    mov.u32 r_by, %ctaid.y;
    mov.u32 r_bz, %ctaid.z;
    // Compute output w start and thread's w index
    mul.lo.u32 r_wout_start, r_bx, r_bdim;
    add.u32 r_wout, r_wout_start, r_tid;
    // Decode blockIdx.y into (n, oc, dout); blockIdx.z -> hout
    mov.u32 r_hout, r_bz;
    mov.u32 r_t, r_by;
    rem.u32 r_dout, r_t, rDout;
    div.u32 r_t, r_t, rDout;
    rem.u32 r_oc, r_t, rCout;
    div.u32 r_n, r_t, rCout;
    // Base offsets for y and z considering padding
    cvt.s32.u32 s_hout, r_hout;
    cvt.s32.u32 s_dout, r_dout;
    cvt.s32.u32 sP, rP;
    sub.s32 s_y_base, s_hout, sP;
    sub.s32 s_z_base, s_dout, sP;
    // Base x (stripe) start considering padding
    cvt.s32.u32 s_wout_start, r_wout_start;
    sub.s32 s_x_base, s_wout_start, sP;
    // Shared memory base pointers
    mov.u64 smem_base, sdata;
    // Layout: weights tile K*K floats at 0; x tiles K planes each of stripe_len floats, 16B aligned
    mul.lo.u32 rKK, rK, rK;
    mul.wide.u32 addr_s, rKK, 4;
    mov.u64 w_sh_ptr, smem_base;
    add.u64 x_sh_ptr, smem_base, addr_s;
    add.u64 x_sh_ptr, x_sh_ptr, 15;
    and.b64 x_sh_ptr, x_sh_ptr, 0xfffffffffffffff0;
    // stripe_len = blockDim.x + K - 1
    mov.u32 r_stripe_len, r_bdim;
    add.u32 r_tmp1, rK, 0xffffffff; // K-1
    add.u32 r_stripe_len, r_stripe_len, r_tmp1;
     // r_smem_stride = align_up(stripe_len, 4) so each plane base is 16B aligned
     add.u32 r_tmp1, r_stripe_len, 3;
     and.b32 r_smem_stride, r_tmp1, 0xfffffffc;
    // Initialize accumulator
    mov.f32 acc, 0f00000000;
    // Precompute vector window for X stripe
    // s_start = max(0, s_x_base)
    setp.lt.s32 p0, s_x_base, 0;
    selp.s32 s_start, 0, s_x_base, p0;
    // s_end = min(W, s_x_base + stripe_len)
    add.s32 s_tmpa, s_x_base, r_stripe_len;
    setp.lt.s32 p1, rW, s_tmpa;
    selp.s32 s_end, rW, s_tmpa, p1;
    // s_mid_start = align_up(s_start, 4)
    cvt.u32.s32 r_tmp_u0, s_start;
    and.b32 r_tmp_u1, r_tmp_u0, 3;
    setp.eq.u32 pal0, r_tmp_u1, 0;
    sub.u32 r_tmp_u0, 4, r_tmp_u1;
    selp.u32 r_tmp_u0, 0, r_tmp_u0, pal0;
    cvt.s32.u32 s_tmpb, r_tmp_u0;
    add.s32 s_mid_start, s_start, s_tmpb;
    // s_mid_end = align_down(s_end, 4)
    cvt.u32.s32 r_tmp_u0, s_end;
    and.b32 r_tmp_u0, r_tmp_u0, 0xfffffffc;
    cvt.s32.u32 s_mid_end, r_tmp_u0;
    // left count = clamp(s_mid_start - s_x_base, 0..stripe_len)
    sub.s32 s_tmpa, s_mid_start, s_x_base;
    setp.lt.s32 pL, s_tmpa, 0;
    selp.s32 s_tmpa, 0, s_tmpa, pL;
    cvt.u32.s32 r_left_cnt, s_tmpa;
    setp.gt.u32 pL, r_left_cnt, r_stripe_len;
    selp.u32 r_left_cnt, r_stripe_len, r_left_cnt, pL;
    // vec_len base = max(0, (s_mid_end - s_mid_start) >> 2)
    sub.s32 s_tmpb, s_mid_end, s_mid_start;
    setp.lt.s32 pV, s_tmpb, 0;
    selp.s32 s_tmpb, 0, s_tmpb, pV;
    cvt.u32.s32 r_vec_len, s_tmpb;
    shr.u32 r_vec_len, r_vec_len, 2;
    // right count = clamp((s_x_base + stripe_len) - s_mid_end, 0..stripe_len)
    add.s32 s_tmpa, s_x_base, r_stripe_len;
    sub.s32 s_tmpa, s_tmpa, s_mid_end;
    setp.lt.s32 pR, s_tmpa, 0;
    selp.s32 s_tmpa, 0, s_tmpa, pR;
    cvt.u32.s32 r_right_cnt, s_tmpa;
    // r_vec_off_base = (s_mid_start - s_x_base)
    sub.s32 s_tmpa, s_mid_start, s_x_base;
    cvt.u32.s32 r_vec_off_base, s_tmpa;
    // Loop over input channels and kernel depth
    mov.u32 r_ic, 0;
IC_LOOP:
    setp.ge.u32 p2, r_ic, rCin;
    @p2 bra END_IC;
    mov.u32 r_kz, 0;
KZ_LOOP:
    setp.ge.u32 p3, r_kz, rK;
    @p3 bra END_KZ;
    // z coordinate and predicate
    cvt.s32.u32 s_y, r_kz; // reuse s_y as temp
    add.s32 s_z, s_z_base, s_y;
    setp.ge.s32 pz0, s_z, 0;
    setp.lt.s32 pz1, s_z, rD;
    and.pred pz_ok, pz0, pz1;
    // Compute base_w0 = ((((oc*Cin + ic)*K + kz)*K + 0)*K)
    mul.lo.u32 r_tmp1, r_oc, rCin;
    add.u32    r_tmp1, r_tmp1, r_ic;
    mul.lo.u32 r_tmp1, r_tmp1, rK;
    add.u32    r_tmp1, r_tmp1, r_kz;
    mul.lo.u32 r_tmp1, r_tmp1, rK;       // base_pre
    mul.lo.u32 r_base_w, r_tmp1, rK;     // base_w0
    // Cooperative load of K*K weights into shared memory
    mul.lo.u32 rKK, rK, rK;
    mov.u32 r_t, r_tid;
W_TILE_LOAD_LOOP:
    setp.ge.u32 p4, r_t, rKK;
    @p4 bra W_TILE_LOAD_DONE;
    add.u32 r_w_idx, r_base_w, r_t;
    cvt.u64.u32 addr_w, r_w_idx;
    shl.b64     addr_w, addr_w, 2;
    add.u64     addr_w, addr_w, wbase;
    ld.global.f32 wval, [addr_w];
    mul.wide.u32 addr_s, r_t, 4;
    add.u64     addr_s, w_sh_ptr, addr_s;
    st.shared.f32 [addr_s], wval;
    add.u32 r_t, r_t, r_bdim;
    bra W_TILE_LOAD_LOOP;
W_TILE_LOAD_DONE:
    // Prepare Z as unsigned for indexing
    cvt.u32.s32 ru_sz, s_z;
    // Load K X-planes (each of stripe_len) into shared memory
    mov.u32 r_ky, 0;
KY_LOAD_LOOP:
    setp.ge.u32 p5, r_ky, rK;
    @p5 bra KY_LOAD_DONE;
    // y coordinate and predicate for this ky
    cvt.s32.u32 s_y, r_ky;
    add.s32 s_y, s_y_base, s_y;
    setp.ge.s32 py0, s_y, 0;
    setp.lt.s32 py1, s_y, rH;
    and.pred py_ok, py0, py1;
    and.pred p_yz_ok, pz_ok, py_ok;
    // plane base pointer: x_sh_ptr + (ky * stripe_len) * 4
     mul.lo.u32 r_plane_off, r_ky, r_smem_stride;
    mul.wide.u32 addr_plane, r_plane_off, 4;
    add.u64     addr_plane, x_sh_ptr, addr_plane;
    @p_yz_ok bra LOAD_PLANE;
    // Not in bounds for y or z: fill plane with zeros
    mov.u32 r_t, r_tid;
PLANE_ZERO_LOOP:
    setp.ge.u32 p6, r_t, r_stripe_len;
    @p6 bra PLANE_ZERO_DONE;
    mul.wide.u32 addr_s, r_t, 4;
    add.u64     addr_s, addr_plane, addr_s;
    st.shared.f32 [addr_s], 0f00000000;
    add.u32 r_t, r_t, r_bdim;
    bra PLANE_ZERO_LOOP;
PLANE_ZERO_DONE:
    bra PLANE_DONE;
LOAD_PLANE:
    // Convert y to unsigned and compute base0 for this row
    cvt.u32.s32 ru_sy, s_y;
    // base0 = (((n*Cin + ic)*D + z)*H + y) * W
    mul.lo.u32 r_tmp2, r_n, rCin;
    add.u32    r_tmp2, r_tmp2, r_ic;
    mul.lo.u32 r_tmp2, r_tmp2, rD;
    add.u32    r_tmp2, r_tmp2, ru_sz;
    mul.lo.u32 r_tmp2, r_tmp2, rH;
    add.u32    r_tmp2, r_tmp2, ru_sy;
    mul.lo.u32 r_base0, r_tmp2, rW;
    // Alignment check for vector path on this row
    and.b32 r_align0, r_base0, 3;
    mov.u32 r_vec_len2, r_vec_len;
    setp.eq.u32 pal1, r_align0, 0;
    @!pal1 mov.u32 r_vec_len2, 0;
     // Also require shared destination alignment for vector path
     and.b32 r_tmp_u0, r_vec_off_base, 3;
     setp.eq.u32 pal2, r_tmp_u0, 0;
     @!pal2 mov.u32 r_vec_len2, 0;
    // Phase A: left scalar region (with per-element bounds)
    mov.u32 r_t, r_tid;
LEFT_SCALAR_LOOP_ROW:
    setp.ge.u32 pL, r_t, r_left_cnt;
    @pL bra LEFT_SCALAR_DONE_ROW;
    add.s32 s_xi, s_x_base, r_t;
    setp.ge.s32 px0, s_xi, 0;
    setp.lt.s32 px1, s_xi, rW;
    and.pred px_ok, px0, px1;
    @!px_ok bra LEFT_STORE_ZERO_ROW;
    cvt.u32.s32 ru_sx, s_xi;
    add.u32    r_x_idx, r_base0, ru_sx;
    cvt.u64.u32 addr_x, r_x_idx;
    shl.b64     addr_x, addr_x, 2;
    add.u64     addr_x, addr_x, xbase;
    ld.global.f32 xval, [addr_x];
    mul.wide.u32 addr_s, r_t, 4;
    add.u64     addr_s, addr_plane, addr_s;
    st.shared.f32 [addr_s], xval;
    bra LEFT_STORE_DONE_ROW;
LEFT_STORE_ZERO_ROW:
    mul.wide.u32 addr_s, r_t, 4;
    add.u64     addr_s, addr_plane, addr_s;
    st.shared.f32 [addr_s], 0f00000000;
LEFT_STORE_DONE_ROW:
    add.u32 r_t, r_t, r_bdim;
    bra LEFT_SCALAR_LOOP_ROW;
LEFT_SCALAR_DONE_ROW:
    // Phase B: vectorized middle region
    mov.u32 r_t, r_tid;
VEC_LOOP_ROW:
    setp.ge.u32 pV, r_t, r_vec_len2;
    @pV bra VEC_DONE_ROW;
    // offset_elems = r_vec_off_base + (r_t << 2)
    shl.b32 r_off_elems, r_t, 2;
    add.u32 r_off_elems, r_off_elems, r_vec_off_base;
    // ru_sx = s_mid_start + (r_t << 2)
    shl.b32 r_tmp1, r_t, 2;
    add.s32 s_tmpa, s_mid_start, r_tmp1;
    cvt.u32.s32 ru_sx, s_tmpa;
    // Global address
    add.u32    r_x_idx, r_base0, ru_sx;
    cvt.u64.u32 addr_xv, r_x_idx;
    shl.b64     addr_xv, addr_xv, 2;
    add.u64     addr_xv, addr_xv, xbase;
    // Load 4 floats and store to shared
    ld.global.v4.f32 {vx0, vx1, vx2, vx3}, [addr_xv];
    mul.wide.u32 addr_sv, r_off_elems, 4;
    add.u64     addr_sv, addr_plane, addr_sv;
    st.shared.v4.f32 [addr_sv], {vx0, vx1, vx2, vx3};
    add.u32 r_t, r_t, r_bdim;
    bra VEC_LOOP_ROW;
VEC_DONE_ROW:
    // Phase C: right scalar region (with per-element bounds)
    // r_tail_start = (s_mid_end - s_x_base)
    sub.s32 s_tmpa, s_mid_end, s_x_base;
    cvt.u32.s32 r_tail_start, s_tmpa;
    mov.u32 r_t, r_tid;
RIGHT_SCALAR_LOOP_ROW:
    setp.ge.u32 pR, r_t, r_right_cnt;
    @pR bra RIGHT_SCALAR_DONE_ROW;
    add.u32 r_off_elems, r_tail_start, r_t;
    add.s32 s_xi, s_x_base, r_off_elems;
    setp.ge.s32 px0, s_xi, 0;
    setp.lt.s32 px1, s_xi, rW;
    and.pred px_ok, px0, px1;
    @!px_ok bra RIGHT_STORE_ZERO_ROW;
    cvt.u32.s32 ru_sx, s_xi;
    add.u32    r_x_idx, r_base0, ru_sx;
    cvt.u64.u32 addr_x, r_x_idx;
    shl.b64     addr_x, addr_x, 2;
    add.u64     addr_x, addr_x, xbase;
    ld.global.f32 xval, [addr_x];
    mul.wide.u32 addr_s, r_off_elems, 4;
    add.u64     addr_s, addr_plane, addr_s;
    st.shared.f32 [addr_s], xval;
    bra RIGHT_STORE_DONE_ROW;
RIGHT_STORE_ZERO_ROW:
    mul.wide.u32 addr_s, r_off_elems, 4;
    add.u64     addr_s, addr_plane, addr_s;
    st.shared.f32 [addr_s], 0f00000000;
RIGHT_STORE_DONE_ROW:
    add.u32 r_t, r_t, r_bdim;
    bra RIGHT_SCALAR_LOOP_ROW;
RIGHT_SCALAR_DONE_ROW:
PLANE_DONE:
    add.u32 r_ky, r_ky, 1;
    bra KY_LOAD_LOOP;
KY_LOAD_DONE:
    // Sync before using shared memory
    bar.sync 0;
    // Accumulate using shared weights tile and x planes
    mov.u32 r_ky, 0;
KY_COMP_LOOP:
    setp.ge.u32 p6, r_ky, rK;
    @p6 bra KY_COMP_DONE;
    // plane base pointer for ky
     mul.lo.u32 r_plane_off, r_ky, r_smem_stride;
    mul.wide.u32 addr_plane, r_plane_off, 4;
    add.u64     addr_plane, x_sh_ptr, addr_plane;
    // kx loop
    mov.u32 r_kx, 0;
KX_COMP_LOOP:
    setp.ge.u32 p7, r_kx, rK;
    @p7 bra KX_COMP_DONE;
    // w index in shared: (ky*K + kx)
    mul.lo.u32 r_tmp1, r_ky, rK;
    add.u32    r_tmp1, r_tmp1, r_kx;
    mul.wide.u32 addr_sw, r_tmp1, 4;
    add.u64     addr_sw, w_sh_ptr, addr_sw;
    ld.shared.f32 wval2, [addr_sw];
    // x index in shared: tid + kx
    add.u32 r_tmp2, r_tid, r_kx;
    mul.wide.u32 addr_sx, r_tmp2, 4;
    add.u64     addr_sx, addr_plane, addr_sx;
    ld.shared.f32 xval2, [addr_sx];
    fma.rn.f32 acc, xval2, wval2, acc;
    add.u32 r_kx, r_kx, 1;
    bra KX_COMP_LOOP;
KX_COMP_DONE:
    add.u32 r_ky, r_ky, 1;
    bra KY_COMP_LOOP;
KY_COMP_DONE:
    // Sync before next kz to avoid hazards on shared memory
    bar.sync 0;
    add.u32 r_kz, r_kz, 1;
    bra KZ_LOOP;
END_KZ:
    add.u32 r_ic, r_ic, 1;
    bra IC_LOOP;
END_IC:
    // Add bias if present
    setp.eq.u32 pbias0, rHasBias, 0;
    @pbias0 bra NO_BIAS;
    cvt.u64.u32 addr_b, r_oc;
    shl.b64 addr_b, addr_b, 2;
    add.u64 addr_b, addr_b, bbase;
    ld.global.f32 bval, [addr_b];
    add.f32 acc, acc, bval;
NO_BIAS:
    // Store only if within Wout
    setp.ge.u32 pstore, r_wout, rWout;
    @pstore bra END;
    // y index: (((((n*Cout + oc)*Dout + dout)*Hout + hout)*Wout + wout))
    mul.lo.u32 r_tmp3, r_n, rCout;
    add.u32    r_tmp3, r_tmp3, r_oc;
    mul.lo.u32 r_tmp3, r_tmp3, rDout;
    add.u32    r_tmp3, r_tmp3, r_dout;
    mul.lo.u32 r_tmp3, r_tmp3, rHout;
    add.u32    r_tmp3, r_tmp3, r_hout;
    mul.lo.u32 r_tmp3, r_tmp3, rWout;
    add.u32    r_tmp3, r_tmp3, r_wout;
    cvt.u64.u32 addr_y, r_tmp3;
    shl.b64 addr_y, addr_y, 2;
    add.u64 addr_y, addr_y, ybase;
    st.global.f32 [addr_y], acc;
END:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv3d_ncdhw")
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, (tuple, list)):
            assert len(kernel_size) == 3 and kernel_size[0] == kernel_size[1] == kernel_size[2], "Only cubic kernels supported."
            k = int(kernel_size[0])
        else:
            k = int(kernel_size)
        assert groups == 1, "groups != 1 not supported"
        assert stride == 1, "stride != 1 not supported"
        assert dilation == 1, "dilation != 1 not supported"
        assert padding >= 0, "padding must be non-negative"
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = k
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        self.has_bias = bool(bias)
        # Parameters: weight [out_channels, in_channels, K, K, K], optional bias [out_channels]
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, k, k, k))
        if self.has_bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)
        # Match nn.Conv3d initialization
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.has_bias:
            fan_in = self.in_channels * (k * k * k)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 supported"
        assert x.is_contiguous(), "Input must be contiguous"
